export function ImportAction({
  fileName = "{{fileName}}",
  rowCount = "{{rowCount}}",
  status = "{{status}}",
  skipDuplicates = {{skipDuplicates}},
  accent = "{{accent}}",
}) {
  const statusText = {
    Ready: ["Ready to import", "#14351f"],
    Validating: ["Validating rows…", "#7a5a10"],
    Error: ["3 rows have missing emails", "#a32020"],
  }[status];
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", width: 300, padding: "16px 18px", borderRadius: 12, boxSizing: "border-box", border: "1px solid #24143018" }}>
      <p style={{ margin: "0 0 8px", fontWeight: 700 }}>{fileName} <span style={{ fontWeight: 400, color: "#24143099" }}>&middot; {rowCount}</span></p>
      <p style={{ margin: "0 0 8px", fontSize: 12, fontWeight: 700, color: statusText[1] }}>{statusText[0]}</p>
      {skipDuplicates && <p style={{ margin: "0 0 12px", fontSize: 11, color: "#24143088" }}>Duplicate contacts will be skipped.</p>}
      <button type="button" style={{ width: "100%", padding: 10, borderRadius: 8, border: "none", background: accent, color: "#14351f", fontWeight: 700, cursor: "pointer" }}>Import {rowCount}</button>
    </div>
  );
}
